function mergeLeft(orders, custMap) {
  return orders.map((o) => ({ ...o, tier: custMap[o.cid] ?? null }));
}
const orders = [{ oid: 1, cid: 'C1' }, { oid: 2, cid: 'C9' }, { oid: 3, cid: 'C1' }];
const custMap = { C1: 'gold', C2: 'silver' };
const merged = mergeLeft(orders, custMap);
console.log('rows preserved: ' + (merged.length === orders.length));
console.log('unmatched: ' + merged.filter((r) => r.tier === null).length);
console.log('tiers=' + merged.map((r) => r.tier || 'NULL').join(','));

